<script setup lang="ts">
import { onMounted,onUnmounted,ref } from 'vue'
import { api,errorText } from '../api'
import { useLoad,time,shortId } from '../composables'
import type { Page } from '../types'
import PageState from './PageState.vue'
import PaginationBar from './PaginationBar.vue'
interface Delivery {runId:string;incidentId:string;targetId:string;targetName:string;status:string;deliveryState:string;attempts:number;errorCode:string;createdAt:string}
const page=ref(0),selected=ref<Delivery|null>(null),reason=ref(''),busy=ref(false),saveError=ref('')
const {data,loading,error,load}=useLoad(()=>api<Page<Delivery>>(`/admin/agent-deliveries?page=${page.value}&size=10`))
async function retry(){if(!selected.value)return;busy.value=true;saveError.value='';try{await api('/agent-runs/'+selected.value.runId+'/retry',{method:'POST',body:{reason:reason.value}});selected.value=null;reason.value='';page.value=0;await load()}catch(e){saveError.value=errorText(e)}finally{busy.value=false}}
onMounted(load);const timer=setInterval(()=>{if(!document.hidden&&!loading.value&&!busy.value)void load()},5000);onUnmounted(()=>clearInterval(timer))
</script>
<template><section class="panel delivery-panel"><div class="panel-heading"><div><h2>诊断投递恢复 <span class="heading-count">{{ data?.total||0 }}</span></h2><p class="muted">管理员查看失败投递元数据；报告证据仍按值班与审计权限访问。</p></div><button class="btn" :disabled="loading" @click="load">刷新投递</button></div><form v-if="selected" class="inline-form" @submit.prevent="retry"><h3>重试 {{ selected.targetName }} · {{ shortId(selected.runId) }}</h3><p class="muted">先修复内部服务或配置。相同任务 ID 继续使用已保存的检查点。</p><div v-if="saveError" class="error-message" role="alert">{{ saveError }}</div><label>重试理由<input v-model="reason" required maxlength="500" :disabled="busy" /></label><div class="form-actions"><button type="button" class="btn" :disabled="busy" @click="selected=null">取消</button><button class="btn primary" :disabled="busy||!reason.trim()">{{ busy?'提交中…':'重新加入队列' }}</button></div></form><PageState :loading="loading&&!data" :error="error" :empty="!!data&&!data.items.length" title="没有需要人工恢复的投递" description="诊断发生不可重试错误，或超过重试上限时会在这里显示。" @retry="load"><div class="table-scroll"><table><thead><tr><th>目标 / 任务</th><th>错误</th><th>尝试次数</th><th>请求时间</th><th>操作</th></tr></thead><tbody><tr v-for="delivery in data?.items" :key="delivery.runId"><td><RouterLink :to="'/incidents/'+delivery.incidentId">{{ delivery.targetName }}</RouterLink><small class="muted mono">{{ shortId(delivery.runId) }}</small></td><td><code>{{ delivery.errorCode }}</code></td><td>{{ delivery.attempts }}/5</td><td>{{ time(delivery.createdAt) }}</td><td><span v-if="delivery.errorCode==='AGENT_MODEL_OUTCOME_UNKNOWN'" class="muted">结果待核实，停止重试</span><button v-else class="btn small" :disabled="busy" @click="selected=delivery;reason='';saveError=''">填写理由重试</button></td></tr></tbody></table></div><PaginationBar v-if="data" :page="page" :size="10" :total="data.total" :loading="loading" @change="p=>{page=p;load()}" /></PageState></section></template>
<style scoped>.delivery-panel{margin-top:24px}.panel-heading p{margin-top:8px}td small{display:block;margin-top:4px}.table-scroll{position:relative}</style>
